#!/usr/bin/env python3
"""Combine ../prompts.js and main.gs into Code.gs, the single file pasted into Apps Script."""
from pathlib import Path

here = Path(__file__).resolve().parent
out = here / "Code.gs"
out.write_text(
    "// GENERATED by backend/build.py from prompts.js + backend/main.gs. Edit those, then rerun.\n\n"
    + (here.parent / "prompts.js").read_text()
    + "\n"
    + (here / "main.gs").read_text()
)
print(f"Wrote {out.relative_to(here.parent)}")
